sys_ui_page.client_script:
function actionOK() {
    var ga = new GlideAjax('FieldUpdater');
    ga.addParam('sysparm_name', 'updateField');
    ga.addParam('sysparm_sn_number', g_form.getValue('serial_number'));  // 修复参数格式
    ga.getXML(parseResponse);  // 修正函数名拼写
    return true;
}

function parseResponse(response) {  // 修正函数名拼写
    var answer = response.responseXML.documentElement.getAttribute("answer");
    var result = JSON.parse(answer);  // 正确解析JSON

    if (result.answer === 'OK') {
        GlideModal.get().destroy();
    } else {
        alert('UpdateResult: ' + (result.message || 'unknown error'));  // 修正拼写
        GlideModal.get().destroy();
    }
}
